from rdkit import Chem
import numpy as np
m=Chem.CombineMols(Chem.AddHs(Chem.MolFromSmiles('P(c1ccccc1)(c1ccccc1[S-])c1ccccc1S')),Chem.AddHs(Chem.MolFromSmiles('P(c1ccccc1)(c1ccccc1)c1ccccc1')))
x=np.array([[float(t) for t in line.split()[1:]] for line in open('answer.xyz').readlines()[2:]])
for a,b in [('C','C'),('C','H'),('C','P'),('C','S'),('S','H')]:
 ds=[]
 for bond in m.GetBonds():
  i,j=bond.GetBeginAtomIdx(),bond.GetEndAtomIdx()
  if sorted([m.GetAtomWithIdx(i).GetSymbol(),m.GetAtomWithIdx(j).GetSymbol()])==sorted([a,b]):ds.append(np.linalg.norm(x[i]-x[j]))
 print(a,b,min(ds),max(ds))
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig=plt.figure(figsize=(10,10)); ax=fig.add_subplot(111,projection='3d')
colors={'C':'#333333','H':'#bbbbbb','P':'orange','S':'#dac800','Au':'#d39800'}
for bond in list(m.GetBonds()):
 i,j=bond.GetBeginAtomIdx(),bond.GetEndAtomIdx();ax.plot(*x[[i,j]].T,c='gray',lw=1.5)
for i in [0,13,35]:ax.plot(*x[[i,69]].T,c='#d39800',lw=3)
for i in range(70):
 s='Au' if i==69 else m.GetAtomWithIdx(i).GetSymbol()
 ax.scatter(*x[i],c=colors[s],s={'C':45,'H':15,'S':110,'P':110,'Au':150}[s])
 if s in ['Au','P','S']:ax.text(*x[i],s+str(i))
ax.set_box_aspect([1,1,1]);ax.view_init(azim=-70,elev=25);plt.savefig('structure_check.png')
